//! Independent MPFR 4.2.2 directed-interval references, generated by root.
//! Source SHA/provenance is preserved in the private supplemental packet.
//! The fixed 48 inputs do not establish a universal ULP guarantee.
use matrust::{
    Matrix,
    array::{expm1, log1p},
};
use std::sync::atomic::AtomicBool;

const TSV: &str = include_str!("fixtures/near_zero_mpfr.tsv");

#[derive(Clone, Copy)]
struct Reference {
    function: &'static str,
    corpus: &'static str,
    index: usize,
    input_bits: u64,
    expected_bits: u64,
    max_ulp: u64,
}

fn references() -> Vec<Reference> {
    let mut lines = TSV.lines();
    assert_eq!(
        lines.next(),
        Some("function\tcorpus\tindex\tinput_bits\texpected_bits\tmax_ulp")
    );
    let mut result = Vec::with_capacity(48);
    for function in ["log1p", "expm1"] {
        for corpus in ["tiny", "ordinary", "boundary"] {
            for index in 0..8 {
                let fields: Vec<_> = lines
                    .next()
                    .expect("all 48 references")
                    .split('\t')
                    .collect();
                assert_eq!(fields.len(), 6);
                assert_eq!(fields[0], function);
                assert_eq!(fields[1], corpus);
                assert_eq!(fields[2].parse::<usize>().unwrap(), index);
                assert_eq!(fields[3].len(), 16);
                assert_eq!(fields[4].len(), 16);
                let input_bits = u64::from_str_radix(fields[3], 16).unwrap();
                let expected_bits = u64::from_str_radix(fields[4], 16).unwrap();
                let max_ulp: u64 = fields[5].parse().unwrap();
                let input = f64::from_bits(input_bits);
                let expected = f64::from_bits(expected_bits);
                assert!(input.is_finite());
                assert!(!expected.is_nan());
                if function == "log1p" {
                    assert!(input >= -1.);
                }
                // The criterion was fixed before application comparison.
                assert_eq!(
                    max_ulp,
                    if expected == 0. || expected.is_infinite() {
                        0
                    } else {
                        2
                    }
                );
                result.push(Reference {
                    function,
                    corpus,
                    index,
                    input_bits,
                    expected_bits,
                    max_ulp,
                });
            }
        }
    }
    assert!(lines.next().is_none());
    assert_eq!(result.len(), 48);
    result
}

fn ordered_bits(bits: u64) -> u64 {
    if bits >> 63 == 0 {
        bits | (1 << 63)
    } else {
        !bits
    }
}

fn assert_reference(actual: f64, reference: &Reference) -> u64 {
    let expected = f64::from_bits(reference.expected_bits);
    let actual_bits = actual.to_bits();
    let distance = if expected == 0. || expected.is_infinite() {
        assert_eq!(
            actual_bits, reference.expected_bits,
            "{} {}[{}] exact zero/infinity: input={:016x}",
            reference.function, reference.corpus, reference.index, reference.input_bits
        );
        0
    } else {
        // Finite references must never be accepted as NaN or infinity.
        assert!(
            actual.is_finite(),
            "{} {}[{}] expected finite: input={:016x} actual={actual_bits:016x}",
            reference.function,
            reference.corpus,
            reference.index,
            reference.input_bits
        );
        ordered_bits(actual_bits).abs_diff(ordered_bits(reference.expected_bits))
    };
    assert!(
        distance <= reference.max_ulp,
        "{} {}[{}] input={:016x} expected={:016x} actual={actual_bits:016x} ulp={distance} limit={}",
        reference.function,
        reference.corpus,
        reference.index,
        reference.input_bits,
        reference.expected_bits,
        reference.max_ulp
    );
    distance
}

fn evaluate(function: &str, input: &Matrix) -> Matrix {
    let cancel = AtomicBool::new(false);
    match function {
        "log1p" => log1p(input, &cancel).unwrap(),
        "expm1" => expm1(input, &cancel).unwrap(),
        _ => unreachable!("fixed reference function"),
    }
}

#[test]
fn independent_mpfr48_scalar_results_in_one_and_eight_worker_contexts() {
    let references = references();
    for workers in [1, 8] {
        let pool = rayon::ThreadPoolBuilder::new()
            .num_threads(workers)
            .build()
            .unwrap();
        pool.install(|| {
            assert_eq!(rayon::current_num_threads(), workers);
            let mut maximum = [0u64; 2];
            for (position, reference) in references.iter().enumerate() {
                let input = Matrix::scalar(f64::from_bits(reference.input_bits));
                let alias = input.clone();
                let result = evaluate(reference.function, &input);
                assert_eq!((result.rows(), result.cols(), result.len()), (1, 1, 1));
                maximum[position / 24] =
                    maximum[position / 24].max(assert_reference(result.data()[0], reference));
                assert_eq!(input.data()[0].to_bits(), reference.input_bits);
                assert_eq!(input.data().as_ptr(), alias.data().as_ptr());
                assert_ne!(result.data().as_ptr(), input.data().as_ptr());
            }
            // Printed only by actual test execution; no source-time accuracy claim.
            eprintln!(
                "MPFR48 scalar workers={workers} observed_max_ulp log1p={} expm1={}",
                maximum[0], maximum[1]
            );
        });
    }
}

#[test]
fn independent_mpfr48_column_major_arrays_preserve_shapes_inputs_and_aliases() {
    let references = references();
    for workers in [1, 8] {
        let pool = rayon::ThreadPoolBuilder::new()
            .num_threads(workers)
            .build()
            .unwrap();
        pool.install(|| {
            assert_eq!(rayon::current_num_threads(), workers);
            for group in references.as_chunks::<24>().0 {
                for (rows, cols) in [(1, 24), (24, 1), (4, 6), (6, 4)] {
                    let input = Matrix::from_column_vec(rows, cols,
                        group.iter().map(|reference| f64::from_bits(reference.input_bits)).collect()).unwrap();
                    let alias = input.clone();
                    let result = evaluate(group[0].function, &input);
                    assert_eq!((result.rows(), result.cols(), result.len()), (rows, cols, 24));
                    let mut maximum = 0u64;
                    for ((&actual, &original), reference) in result.data().iter().zip(input.data()).zip(group) {
                        maximum = maximum.max(assert_reference(actual, reference));
                        assert_eq!(original.to_bits(), reference.input_bits);
                    }
                    assert_eq!(input.data().as_ptr(), alias.data().as_ptr());
                    assert_ne!(result.data().as_ptr(), input.data().as_ptr());
                    eprintln!("MPFR48 shaped {} workers={workers} rows={rows} cols={cols} observed_max_ulp={maximum}", group[0].function);
                }
            }
        });
    }
}
